let held = ctx.player.mainHandItem;
if (!held || held.isEmpty()) return;
let idStr = String(held.id);
let isDmgable = held.isDamageableItem();
let isWeapon = isDmgable || idStr.includes('axe') || idStr.includes('sword') || idStr.includes('spear') || idStr.includes('weapon') || idStr.includes('hammer') || idStr.includes('trident') || idStr.includes('tool');
if (!isWeapon) return;

ctx['thrown_stack'] = held.copy();
ctx['thrown_item_id'] = idStr;
ctx['total_damage'] = (ctx['throw_damage'] || 12.0) + 4.0;
ctx.player.setMainHandItem('minecraft:air');
if (ctx.player.containerMenu) { ctx.player.containerMenu.broadcastChanges(); }

global.Stones.setCooldown(ctx.player, 'milestone_berserker', ctx['throw_cooldown'] || 200);
global.Stones.playSound(ctx.player, 'minecraft:item.trident.throw', 'players', 1.2, 0.6);

global.Stones.spawnProjectile(ctx.player, {
    origin: ctx.player.eyePosition,
    direction: ctx.player.lookAngle,
    speed: 2.2,
    gravity: 0.02,
    lifetime: 40,
    hitboxW: 0.8,
    hitboxH: 0.8,
    renderMode: 'MODEL',
    texture: ctx['thrown_item_id']
},
proj => {
    let player = ctx.player;
    if (proj && player && !proj.onDestroyConsumer) {
        proj.onDestroyConsumer = p => {
            let stack = ctx['thrown_stack'];
            if (stack && !stack.isEmpty()) {
                if (stack.isDamageableItem()) {
                    let curDmg = stack.getDamageValue();
                    let maxDmg = stack.getMaxDamage();
                    let nextDmg = curDmg + 1;
                    if (maxDmg > 0 && nextDmg >= maxDmg) {
                        global.Stones.playSound(player, 'minecraft:entity.item.break', 'players', 1.0, 1.0);
                        stack = null;
                    } else {
                        stack.setDamageValue(nextDmg);
                    }
                }

                if (stack && !stack.isEmpty()) {
                    let chance = ctx['return_chance'] || 25.0;
                    let roll = Math.random() * 100.0;

                    if (roll < chance) {
                        if (player.mainHandItem.isEmpty()) {
                            player.setMainHandItem(stack);
                        } else {
                            player.give(stack);
                        }
                        if (player.containerMenu) player.containerMenu.broadcastChanges();
                        global.Stones.playSound(player, 'minecraft:item.armor.equip_netherite', 'players', 1.0, 0.8);
                    } else {
                        let lvl = player.level;
                        if (lvl) {
                            let itemEnt = lvl.createEntity('item');
                            if (itemEnt) {
                                itemEnt.item = stack;
                                itemEnt.setPosition(p.getX(), p.getY(), p.getZ());
                                itemEnt.spawn();
                            }
                        }
                        global.Stones.playSound(player, 'minecraft:entity.item.pickup', 'players', 0.5, 0.5);
                    }
                }
                ctx['thrown_stack'] = null;
            }
        };
    }
    global.Stones.spawnParticles(ctx.player, 'minecraft:sweep_attack', ctx.player.position(), 2, 0.2, 0.2, 0.2, 0.0);
},
(proj, hit) => {
    if (hit && hit.entity) { hit.entity.attack(ctx['total_damage'] || 16.0); }
    global.Stones.playSound(ctx.player, 'minecraft:entity.player.attack.crit', 'players', 1.0, 0.7);
    global.Stones.spawnParticles(ctx.player, 'minecraft:damage_indicator', ctx.player.position(), 10, 0.4, 0.4, 0.4, 0.1);
    proj.discard();
},
(proj, hit) => {
    global.Stones.playSound(ctx.player, 'minecraft:block.anvil.place', 'players', 0.8, 1.4);
    proj.discard();
});

let p = ctx.player;
if (!p) return;

let currentCd = global.Stones.getCooldown ? global.Stones.getCooldown(p, 'milestone_berserker') : 0;
if (currentCd > 0) {
    global.Stones.setCooldown(p, 'milestone_berserker', Math.max(0, currentCd - 20));
}

let speedEffect = net.minecraft.world.effect.MobEffects.MOVEMENT_SPEED;
let MobEffectInstance = net.minecraft.world.effect.MobEffectInstance;
p.addEffect(new MobEffectInstance(speedEffect, 60, 0, false, true));

global.Stones.playSound(p, 'minecraft:entity.player.attack.knockback', 'players', 0.5, 1.4);
global.Stones.spawnParticles(p, 'minecraft:angry_villager', p.position().add(0, 1.5, 0), 3, 0.2, 0.2, 0.2, 0.0);
